import * as React from 'react'
import { cva } from 'class-variance-authority'
import { cn } from '@/lib/utils'

const inputVariants = cva(
  cn(
    'wj-focus-ring w-full rounded-full pl-9 pr-8 text-sm',
    'bg-[var(--color-surface-light)] dark:bg-[var(--color-surface-dark)]',
    'border border-[var(--color-border-light)] dark:border-[var(--color-border-dark)]',
    'text-[var(--color-text-primary-light)] dark:text-[var(--color-text-primary-dark)]',
    'placeholder:text-[var(--color-text-muted-light)] dark:placeholder:text-[var(--color-text-muted-dark)]',
  ),
  {
    variants: {
      size: {
        sm: 'h-9',
        md: 'h-10',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

export interface SearchFieldProps {
  value: string
  onChange: (value: string) => void
  /** Accessible name for the input -- the placeholder is not a label. */
  label: string
  /** Accessible name AND hover title for the icon-only clear button. */
  clearLabel: string
  placeholder?: string
  /** False takes the field (and its clear button) out of the tab order while
   * a wrapper keeps it mounted but visually collapsed -- a zero-width input
   * still catches Tab, and a focus ring on an invisible field reads as the
   * focus having vanished. Pair with `HeaderStandIn`'s `shown`. */
  tabbable?: boolean
  /** `md` (h-10) matches the DS control baseline; `sm` (h-9) sits flush in
   * denser chrome (a 64px header row, a sidebar rail). */
  size?: 'sm' | 'md'
  autoFocus?: boolean
  className?: string
}

/**
 * Search pill: a rounded-full text input with a leading magnifier and a
 * trailing clear button that appears once there is anything to clear.
 * Controlled and i18n-agnostic -- pass translated `label`, `clearLabel` and
 * `placeholder`. Inline SVG glyphs so the design system stays icon-free
 * (apps own that decision).
 */
export const SearchField = React.forwardRef<HTMLDivElement, SearchFieldProps>(
  (
    { value, onChange, label, clearLabel, placeholder, tabbable = true, size, autoFocus, className },
    ref,
  ) => {
    const tabIndex = tabbable ? undefined : -1
    return (
      <div ref={ref} className={cn('relative', className)}>
        <svg
          className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 pointer-events-none text-[var(--color-text-muted-light)] dark:text-[var(--color-text-muted-dark)]"
          viewBox="0 0 16 16"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          aria-hidden
        >
          <circle cx="7" cy="7" r="4.5" />
          <path d="M10.5 10.5L14 14" />
        </svg>
        <input
          type="text"
          value={value}
          autoFocus={autoFocus}
          tabIndex={tabIndex}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          aria-label={label}
          className={inputVariants({ size })}
        />
        {value && (
          <button
            type="button"
            onClick={() => onChange('')}
            aria-label={clearLabel}
            title={clearLabel}
            tabIndex={tabIndex}
            className="wj-focus-ring absolute right-2 top-1/2 -translate-y-1/2 rounded-full p-1 text-[var(--color-text-muted-light)] dark:text-[var(--color-text-muted-dark)] hover:text-[var(--color-text-primary-light)] dark:hover:text-[var(--color-text-primary-dark)]"
          >
            <svg
              className="w-3.5 h-3.5"
              viewBox="0 0 14 14"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              aria-hidden
            >
              <path d="M3 3l8 8M11 3l-8 8" />
            </svg>
          </button>
        )}
      </div>
    )
  },
)
SearchField.displayName = 'SearchField'
